 "content": "def transform(grid):
    # The diagonal track positions encode values down the grid. Recover the
    # horizontal bands from their markers and tile the six-row band pattern.
    markers = {}
    for row in grid:
        for value in row:
            if value:
                markers.setdefault(value, []).append(row.index(value))
    # In this pattern, 5 is a horizontal divider, while 4 and 3 are
    # diagonal tracks. Their rows are identified from the occupied columns.
    n = len(grid)
    bands = []
    for r, row in enumerate(grid):
        vals = [v for v in row if v]
        if vals and len(vals) >= len(row) // 2:
            bands.append(vals[0])
    # The source is a 26x26 encoding with four horizontal stripe types and
    # diagonal-coded sequence; output repeats the stripe order.
    # Extract the non-background color sequence in its encoded traversal.
    sequence = []
    for r, row in enumerate(grid):
        vals = [v for v in row if v]
        if len(vals) >= len(row) // 2:
            sequence.append(vals[0])
        elif vals:
            # A diagonal component's color is its unique nonzero value.
            sequence.append(vals[0])
    # All examples follow this repeating 6-row motif after ordering the two
    # bottom bands first.
    if len(sequence) >= 6:
        motif = sequence[-2:] + sequence[:-2]
        return [[motif[i % len(motif)]] * len(row) for i, row in enumerate(grid)]
    return [row[:] for row in grid]
