    # Each diagonal strand is an output color for one residue of (column-row).
    # Learn residue->color mapping from the input's diagonal lines.
    strands = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                strands.setdefault(d, color)
    period = len(strands)
    mapping = {d % period: color for d, color in strands.items()}
    return [[mapping[(c-r) % period] for c in range(w)] for r in range(h)]
